module ShareTracker (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire in_valid,\n    input wire [8:0] in_day,\n    input wire [9:0] in_shares,\n    output reg out_valid,\n    output reg [8:0] out_day,\n    output reg [19:0] out_shares,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] COLLECT = 3'd1;\n    localparam [2:0] OUTPUT  = 3'd2;\n    localparam [2:0] FINISH  = 3'd3;\n    \n    // State registers\n    reg [2:0] state;\n    reg [2:0] next_state;\n    \n    // Day memory: 365 entries of 20-bit sums\n    reg [19:0] day_sums [0:364];\n    \n    // Output scanning\n    reg [8:0] scan_day;\n    reg output_started;\n    \n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n    \n    // Next state logic\n    always @(*) begin\n        case (state)\n            IDLE: begin\n                if (start)\n                    next_state = COLLECT;\n                else\n                    next_state = IDLE;\n            end\n            \n            COLLECT: begin\n                if (!in_valid) \n                    next_state = OUTPUT;\n                else\n                    next_state = COLLECT;\n            end\n            \n            OUTPUT: begin\n                if (scan_day >= 9'd364 && output_started)\n                    next_state = FINISH;\n                else\n                    next_state = OUTPUT;\n            end\n            \n            FINISH: begin\n                next_state = FINISH;\n            end\n            \n            default: next_state = IDLE;\n        endcase\n    end\n    \n    // Main logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize memory\n            integer i;\n            for (i = 0; i < 365; i = i + 1) begin\n                day_sums[i] <= 20'd0;\n            end\n            \n            out_valid <= 1'b0;\n            out_day <= 9'd0;\n            out_shares <= 20'd0;\n            done <= 1'b0;\n            scan_day <= 9'd0;\n            output_started <= 1'b0;\n        end else begin\n            case (state)\n                COLLECT: begin\n                    if (in_valid) begin\n                        // Add shares to day sum (day_in is 1-365, convert to 0-364)\n                        if (in_day >= 9'd1 && in_day <= 9'd365) begin\n                            day_sums[in_day - 9'd1] <= day_sums[in_day - 9'd1] + in_shares;\n                        end\n                    end\n                    out_valid <= 1'b0;\n                    done <= 1'b0;\n                end\n                \n                OUTPUT: begin\n                    if (!output_started) begin\n                        scan_day <= 9'd0;\n                        output_started <= 1'b1;\n                        out_valid <= 1'b0;\n                    end else begin\n                        // Check current day\n                        if (day_sums[scan_day] != 20'd0) begin\n                            out_valid <= 1'b1;\n                            out_day <= scan_day + 9'd1;  // Convert back to 1-365\n                            out_shares <= day_sums[scan_day];\n                        end else begin\n                            out_valid <= 1'b0;\n                        end\n                        \n                        // Advance to next day\n                        if (scan_day < 9'd364) begin\n                            scan_day <= scan_day + 9'd1;\n                        end\n                    end\n                    done <= 1'b0;\n                end\n                \n                FINISH: begin\n                    out_valid <= 1'b0;\n                    done <= 1'b1;\n                end\n                \n                default: begin\n                    out_valid <= 1'b0;\n                    done <= 1'b0;\n                end\n            endcase\n        end\n    end\nendmodule